_MEAN = [["gusto, ibig, nais", "want (to), like (to), would like (to)"], ["ayaw", "do not like, do not want"], ["kailangan", "have to, need to"], ["puwede, maaari", "can, could, it is possible"], ["dapat", "ought to, should"]]
_PV = [("Puwedeng mag-aral ka na lang sa Linggo?", "Can you (just) study on Sunday instead?"), ("Kailangang mag-aral ako sa Sabado.", "I need to study this Saturday."), ("Gusto mo bang sumama sa San Francisco ngayong Sabado?", "Do you like to come to San Francisco this Saturday?"), ("Gusto mo bang kumain sa labas ngayong weekend?", "Do you want to eat out this weekend?"), ("Dapat mag-relax ka naman kapag weekend.", "You should relax too during the weekend.")]
